document.addEventListener("DOMContentLoaded",()=>{if(!window.matchMedia("(min-width: 769px)").matches)return;const e=document.querySelectorAll("sup[id^='fnref']");e.forEach(e=>{const n=e.querySelector("a");if(!n)return;const o=n.getAttribute("href")?.slice(1),s=document.getElementById(o);if(!s)return;const t=document.createElement("span");t.className="sidenote",t.innerHTML=s.innerHTML.replace(/↩︎?/,""),e.after(t)})})